<?php
require_once __DIR__.'/core.php';tt_require_login();$db=tt_db_open(true);$counts=[];foreach(['accounts','posts','groups','events','forums','post_attachments','post_tags','tag_index'] as $t){$r=$db->query('SELECT COUNT(*) AS `n` FROM `'.$t.'`');$counts[$t]=$r?(int)($r->fetch_assoc()['n']??0):0;if($r)$r->free();}$types=[];$r=$db->query('SELECT `type`,COUNT(*) AS `n` FROM `posts` GROUP BY `type` ORDER BY `n` DESC');if($r){while($x=$r->fetch_assoc())$types[]=$x;$r->free();}$db->close();
?><!doctype html><html class="tabletime"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.php"><title>Tabletime · Stats</title></head><body><?php tt_nav();?><main class="content"><h2>Tabletime statistics</h2><section class="grid"><?php foreach($counts as $k=>$v):?><article class="card"><h3><?=tt_h($k)?></h3><p><?=number_format($v)?></p></article><?php endforeach;?></section><h3>Post types</h3><table><tr><th>Type</th><th>Count</th></tr><?php foreach($types as $x):?><tr><td><?=tt_h($x['type'])?></td><td><?=number_format((int)$x['n'])?></td></tr><?php endforeach;?></table></main></body></html>